# LBDS Animated Props v0.6.5 — RPG Maker XP / La Base de Sky v21.1 (dev)
# Reads Data/AnimatedProps/objects.json generated by the Maker Studio mod.
# Keeps animations external to native tiles and does NOT patch rxdata files.
# This file is loaded by the regular Essentials PluginManager.
# Requires JSON.parse from the engine's Ruby standard library; no JSON Compatibility plugin.

module LBDSAnimatedProps
  DATA_FILE = 'Data/AnimatedProps/objects.json' unless const_defined?(:DATA_FILE, false)
  ART_DIR = 'Graphics/AnimatedProps/' unless const_defined?(:ART_DIR, false)
  CELL_SIZE = 32 unless const_defined?(:CELL_SIZE, false)
  # Limits source-rectangle updates, NOT animation elapsed time. Set 0 to
  # remove the cap, or 60 for full 60 FPS animation sampling.
  DISPLAY_FPS_CAP = 30 unless const_defined?(:DISPLAY_FPS_CAP, false)
  module_function

  def data
    return @data if @data
    @data = { 'definitions' => [], 'placements' => {} }
    return @data unless File.file?(DATA_FILE)
    unless defined?(JSON) && JSON.respond_to?(:parse)
      warn '[LBDS Animated Props] Falta JSON.parse: revisa rubyLoadpath y stdlib (Ruby 3.1).'
      return @data
    end
    candidate = JSON.parse(File.binread(DATA_FILE))
    unless candidate.is_a?(Hash) && candidate['schema'] == 1
      warn 'LBDS Animated Props: formato de objects.json no soportado.'
      return @data
    end
    @data = candidate
  rescue StandardError => e
    warn "LBDS Animated Props: #{e.class}: #{e.message}"
    @data
  end

  def phase_from_id(id, frames)
    hash = 2_166_136_261
    id.to_s.each_byte { |b| hash = ((hash ^ b) * 16_777_619) & 0xffffffff }
    hash % [frames.to_i, 1].max
  end

  def clear_cache!
    @data = nil
  end

  def valid_sheet?(sheet)
    sheet.is_a?(String) && sheet.match?(/\A[\p{L}\p{N}_() .-]+\.png\z/i)
  end

  def map_placements(map_id)
    placements = data['placements']
    return [] unless placements.is_a?(Hash)
    items = placements[map_id.to_i.to_s]
    return [] unless items.is_a?(Array)
    definitions = data['definitions']
    return [] unless definitions.is_a?(Array)
    defs = definitions.each_with_object({}) do |d, memo|
      memo[d['id']] = d if d.is_a?(Hash) && d['id'].is_a?(String)
    end
    items.filter_map do |p|
      next unless p.is_a?(Hash)
      definition = defs[p['defId']]
      next unless definition && valid_sheet?(definition['sheet'])
      w, h = definition['width'].to_i, definition['height'].to_i
      f, fps = definition['frames'].to_i, definition['fps'].to_i
      next unless (1..32).cover?(w) && (1..32).cover?(h)
      next unless (1..64).cover?(f) && (1..60).cover?(fps)
      next unless p['x'].is_a?(Integer) && p['y'].is_a?(Integer)
      next if p['x'] < 0 || p['y'] < 0
      cells = definition['cells']
      next unless cells.is_a?(Array) && cells.length == w * h
      next unless cells.all? { |cell| cell.is_a?(Hash) }
      # v0.3.0: a placement can select any rectangular subset of the animated
      # sprite. The original frame stride remains the definition's full width.
      crop = p['crop'].is_a?(Hash) ? p['crop'] : {}
      sx = [[crop.fetch('x', 0).to_i, 0].max, w - 1].min
      sy = [[crop.fetch('y', 0).to_i, 0].max, h - 1].min
      sw = [[crop.fetch('w', w).to_i, 1].max, w - sx].min
      sh = [[crop.fetch('h', h).to_i, 1].max, h - sy].min
      sliced = sh.times.flat_map do |cy|
        sw.times.map { |cx| cells[(sy + cy) * w + sx + cx] }
      end
      parallel = definition['parallel'].is_a?(Hash) ? definition['parallel'] : {}
      parallel_sheet = parallel['sheet']
      parallel_enabled = parallel['enabled'] == true && valid_sheet?(parallel_sheet)
      parallel_frames = [[parallel.fetch('frames', 1).to_i, 1].max, 64].min
      parallel_fps = [[parallel.fetch('fps', 6).to_i, 1].max, 60].min
      overlay = if parallel_enabled
                  { sheet: parallel_sheet, frames: parallel_frames, fps: parallel_fps,
                    loop: parallel['loop'] != false,
                    opacity: [[parallel.fetch('opacity', 100).to_i, 0].max, 100].min,
                    phase: [[parallel.fetch('phase', 0).to_i, 0].max, 63].min }
                end
      { x: p['x'], y: p['y'], width: sw, height: sh, frames: f, fps: fps,
        source_x: sx, source_y: sy, frame_width: w,
        sheet: definition['sheet'], cells: sliced, id: p['id'] || definition['id'],
        timing_mode: definition['timingMode'] == 'independent' ? 'independent' : 'synchronized',
        parallel: overlay,
        layer: [[p.fetch('layer', 0).to_i, 0].max, 99].min,
        loop: definition['loop'] != false }
    end
  end

  # Picks the last placed cell. Like the uppermost tile layer, the most recent
  # object takes precedence where two object's footprints overlap.
  # Some other plugins (for example Overworld Shadows EX) inspect terrain tags
  # while a map is loading. Older savegames also lack our instance variables.
  # An uninitialized lookup must never cause an exception or override terrain.
  def cell_at(map, x, y)
    return nil unless map
    lookup = if map.respond_to?(:lbds_props_lookup_ensure)
               map.lbds_props_lookup_ensure
             elsif map.respond_to?(:lbds_props_lookup)
               map.lbds_props_lookup
             end
    return nil unless lookup.is_a?(Hash)
    cell = lookup[[x, y]]
    cell.is_a?(Hash) ? cell : nil
  end

  # Walkable props never override the passage mask of blocking props below.
  # The topmost cell is still used for terrain / visual properties.
  def passage_mask_at(map, x, y)
    return 0 unless map && map.respond_to?(:lbds_props_lookup_ensure)
    map.lbds_props_lookup_ensure
    lookup = map.respond_to?(:lbds_props_collision_lookup) ? map.lbds_props_collision_lookup : nil
    lookup.is_a?(Hash) ? lookup.fetch([x, y], 0) : 0
  end

  def blocking?(map, x, y, direction)
    mask = passage_mask_at(map, x, y)
    bit = { 2 => 1, 4 => 2, 6 => 4, 8 => 8 }[direction]
    return mask != 0 if bit.nil?
    (mask & bit) != 0
  end

  def movement_blocked?(map, x, y, direction)
    delta = { 2 => [0, 1, 8], 4 => [-1, 0, 6],
              6 => [1, 0, 4], 8 => [0, -1, 2] }[direction]
    return false unless delta && map && map.respond_to?(:lbds_props_lookup_ensure)
    dx, dy, opposite = delta
    map.lbds_props_lookup_ensure
    lookup = map.respond_to?(:lbds_props_collision_lookup) ? map.lbds_props_collision_lookup : nil
    return false unless lookup.is_a?(Hash)
    bits = { 2 => 1, 4 => 2, 6 => 4, 8 => 8 }
    (lookup.fetch([x, y], 0) & bits.fetch(direction)) != 0 ||
      (lookup.fetch([x + dx, y + dy], 0) & bits.fetch(opposite)) != 0
  end
end

module LBDSAnimatedPropsMap
  attr_reader :lbds_props_lookup, :lbds_props_collision_lookup, :lbds_props_placements

  # Do NOT override Game_Map#setup here.  Debug Passability executes
  # `alias old_setup_kodsn setup` in the Game_Map class.  When that alias
  # captures our PREPENDED #setup, super dispatches into an alias loop:
  # MakerStudio FogCommands -> Animated Props -> Debug Passability -> Fog.
  # Lazy cache initialization sidesteps the conflict entirely.
  # If this file is re-evaluated in the same VM, remove the stale v0.6.3
  # setup method left on this module. A cold restart is still recommended.
  remove_method :setup if instance_methods(false).include?(:setup)

  # Builds missing caches lazily for existing savegames, but only when the
  # underlying RPG map has already been loaded. During loading, the ordinary
  # Essentials terrain methods remain authoritative.
  def lbds_props_lookup_ensure
    if @lbds_props_lookup.is_a?(Hash) && @lbds_props_collision_lookup.is_a?(Hash) &&
       @lbds_props_lookup_map_id == @map_id &&
       @lbds_props_lookup_map.equal?(@map)
      return @lbds_props_lookup
    end
    return nil if @lbds_props_initializing || @lbds_props_rebuilding
    return nil unless @map_id && @map_id.to_i > 0 && @map
    lbds_props_rebuild
    @lbds_props_lookup
  end

  def lbds_props_rebuild
    @lbds_props_rebuilding = true
    @lbds_props_placements = LBDSAnimatedProps.map_placements(@map_id)
    @lbds_props_lookup = {}
    @lbds_props_collision_lookup = {}
    @lbds_props_placements.sort_by { |p| p[:layer] }.each do |p|
      p[:height].times do |y|
        p[:width].times do |x|
          next unless valid?(p[:x] + x, p[:y] + y)
          cell = p[:cells][y * p[:width] + x]
          next unless cell.is_a?(Hash)
          key = [p[:x] + x, p[:y] + y]
          @lbds_props_lookup[key] = cell
          passage = cell.fetch('passage', 0).to_i & 0x0f
          if passage != 0
            @lbds_props_collision_lookup[key] = (@lbds_props_collision_lookup[key] || 0) | passage
          end
        end
      end
    end
    @lbds_props_lookup_map_id = @map_id
    @lbds_props_lookup_map = @map
    @lbds_props_lookup
  ensure
    @lbds_props_rebuilding = false
  end

  def passable?(x, y, dir, self_event = nil)
    return false if LBDSAnimatedProps.movement_blocked?(self, x, y, dir)
    super
  end

  def passableStrict?(x, y, dir, self_event = nil)
    return false if LBDSAnimatedProps.movement_blocked?(self, x, y, dir)
    super
  end

  def terrain_tag(x, y, countBridge = false)
    cell = LBDSAnimatedProps.cell_at(self, x, y)
    if cell && cell.fetch('terrainTag', 0).to_i > 0
      tag = GameData::TerrainTag.try_get(cell['terrainTag'].to_i)
      return tag if tag
    end
    super
  end

  def bush?(x, y)
    c = LBDSAnimatedProps.cell_at(self, x, y)
    return true if c && (c.fetch('passage', 0).to_i & 0x40) != 0
    super
  end

  def counter?(x, y)
    c = LBDSAnimatedProps.cell_at(self, x, y)
    return true if c && (c.fetch('passage', 0).to_i & 0x80) != 0
    super
  end
end

# One short sprite per contiguous group of cells of equal priority. The entire
# object advances frames together; split rows allow tile-like draw priority.
module LBDSAnimatedPropsSpriteset
  # Large maps can contain hundreds of animated objects. Only create Sprite
  # instances near the camera, while preserving all priority groups and tracks.
  PROP_BUCKET_SIZE = 16 unless const_defined?(:PROP_BUCKET_SIZE, false)
  PROP_MARGIN_TILES = 3 unless const_defined?(:PROP_MARGIN_TILES, false)

  def initialize(map = nil)
    super
    @lbds_prop_sprites = []
    @lbds_prop_groups = {}
    @lbds_prop_bitmaps = {}
    @lbds_prop_buckets = {}
    @lbds_prop_started_at = System.uptime
    @lbds_prop_geometry_stamp = nil
    lbds_props_build_sprites
    lbds_props_update_sprites
  end

  def lbds_props_bitmap(sheet, p, frames)
    bitmap = @lbds_prop_bitmaps[sheet]
    unless bitmap
      begin
        bitmap = Bitmap.new(LBDSAnimatedProps::ART_DIR + sheet)
        @lbds_prop_bitmaps[sheet] = bitmap
      rescue StandardError => e
        warn "LBDS Animated Props: no se pudo cargar #{sheet}: #{e.message}"
        return nil
      end
    end
    expected_width = p[:frame_width] * LBDSAnimatedProps::CELL_SIZE * frames
    expected_height = (p[:source_y] + p[:height]) * LBDSAnimatedProps::CELL_SIZE
    if bitmap.width < expected_width || bitmap.height < expected_height
      warn "LBDS Animated Props: dimensiones incorrectas en #{sheet}; se esperan #{expected_width}x#{expected_height}."
      return nil
    end
    bitmap
  end

  def lbds_props_build_sprites
    return unless @map
    @map.lbds_props_lookup_ensure if @map.respond_to?(:lbds_props_lookup_ensure)
    @lbds_prop_placements = @map.lbds_props_placements || []
    # Spatial bins avoid scanning all map objects every frame or camera movement.
    @lbds_prop_buckets = Hash.new { |h, key| h[key] = [] }
    @lbds_prop_placements.each do |p|
      min_x = p[:x] / PROP_BUCKET_SIZE
      min_y = p[:y] / PROP_BUCKET_SIZE
      max_x = (p[:x] + p[:width] - 1) / PROP_BUCKET_SIZE
      max_y = (p[:y] + p[:height] - 1) / PROP_BUCKET_SIZE
      (min_y..max_y).each do |by|
        (min_x..max_x).each do |bx|
          @lbds_prop_buckets[[bx, by]] << p
        end
      end
    end
  end

  # View bounds are expressed in map tile units. The renderer's zoom is already
  # applied to its screen coordinates; invert the same camera transform here.
  def lbds_props_view_bounds(mx, my, zx, zy)
    zx = 1.0 if zx <= 0
    zy = 1.0 if zy <= 0
    half_x = Graphics.width / 2.0
    half_y = Graphics.height / 2.0
    margin_x = PROP_MARGIN_TILES * Game_Map::TILE_WIDTH
    margin_y = PROP_MARGIN_TILES * Game_Map::TILE_HEIGHT
    min_x = (mx + (-margin_x - half_x) / zx + half_x) / Game_Map::TILE_WIDTH.to_f
    max_x = (mx + (Graphics.width + margin_x - half_x) / zx + half_x) / Game_Map::TILE_WIDTH.to_f
    min_y = (my + (-margin_y - half_y) / zy + half_y) / Game_Map::TILE_HEIGHT.to_f
    max_y = (my + (Graphics.height + margin_y - half_y) / zy + half_y) / Game_Map::TILE_HEIGHT.to_f
    [min_x.floor, min_y.floor, max_x.ceil, max_y.ceil]
  end

  def lbds_props_make_group(p)
    group = []
    base = lbds_props_bitmap(p[:sheet], p, p[:frames])
    return group unless base
    parallel = p[:parallel]
    overlay = parallel && lbds_props_bitmap(parallel[:sheet], p, parallel[:frames])
    p[:height].times do |cy|
      cx = 0
      while cx < p[:width]
        cell = p[:cells][cy * p[:width] + cx]
        priority = [[cell.fetch('priority', 0).to_i, 0].max, 5].min
        run = 1
        while cx + run < p[:width]
          another = p[:cells][cy * p[:width] + cx + run]
          break if [[another.fetch('priority', 0).to_i, 0].max, 5].min != priority
          run += 1
        end
        [[:base, base], [:parallel, overlay]].each do |track, bitmap|
          next unless bitmap
          sprite = Sprite.new(Spriteset_Map.viewport)
          sprite.bitmap = bitmap
          sprite.src_rect.set((p[:source_x] + cx) * 32, (p[:source_y] + cy) * 32, run * 32, 32)
          sprite.zoom_x = TilemapRenderer::ZOOM_X
          sprite.zoom_y = TilemapRenderer::ZOOM_Y
          sprite.opacity = (parallel[:opacity] * 255 / 100) if track == :parallel
          # Keep the stable entry layout used by prior integrations/tests.
          group << [sprite, p, cx, cy, run, priority, -1, track]
        end
        cx += run
      end
    end
    group
  end

  def lbds_props_sync_visible(mx, my, zx, zy)
    bounds = lbds_props_view_bounds(mx, my, zx, zy)
    return false if @lbds_prop_active_bounds == bounds
    @lbds_prop_active_bounds = bounds
    min_x, min_y, max_x, max_y = bounds
    candidates = {}
    (min_y / PROP_BUCKET_SIZE..max_y / PROP_BUCKET_SIZE).each do |by|
      (min_x / PROP_BUCKET_SIZE..max_x / PROP_BUCKET_SIZE).each do |bx|
        (@lbds_prop_buckets[[bx, by]] || []).each do |p|
          next if p[:x] + p[:width] < min_x || p[:y] + p[:height] < min_y
          next if p[:x] > max_x || p[:y] > max_y
          candidates[p.object_id] = p
        end
      end
    end
    removed = @lbds_prop_groups.keys - candidates.keys
    removed.each do |key|
      @lbds_prop_groups.delete(key).each do |entry|
        entry[0].dispose unless entry[0].disposed?
      end
    end
    added = false
    candidates.each do |key, p|
      next if @lbds_prop_groups.key?(key)
      @lbds_prop_groups[key] = lbds_props_make_group(p)
      added = true
    end
    if !removed.empty? || added
      @lbds_prop_sprites = @lbds_prop_groups.values.flatten(1)
      @lbds_prop_geometry_stamp = nil
    end
    true
  end

  def lbds_props_update_sprites
    return unless @map && @lbds_prop_sprites
    mx = (@map.display_x.to_f / Game_Map::X_SUBPIXELS).round
    my = (@map.display_y.to_f / Game_Map::Y_SUBPIXELS).round
    zx = TilemapRenderer::ZOOM_X
    zy = TilemapRenderer::ZOOM_Y
    lbds_props_sync_visible(mx, my, zx, zy)
    return if @lbds_prop_sprites.empty?
    visual25d = defined?(Visual25D) && Visual25D.enabled?
    depth_stamp = visual25d ? Visual25D.projection_stamp : nil
    # Al cambiar de proyeccion no conservar coordenadas 2D cacheadas.
    stamp = [mx, my, zx, zy, Graphics.width, Graphics.height, visual25d, depth_stamp]
    geometry_changed = @lbds_prop_geometry_stamp != stamp
    @lbds_prop_geometry_stamp = stamp
    now = System.uptime
    cap = LBDSAnimatedProps::DISPLAY_FPS_CAP.to_i
    slot = cap > 0 ? (now * cap).floor : nil
    # Static camera + unchanged animation sample: avoid iterating sprites.
    return if !geometry_changed && cap > 0 && @lbds_prop_frame_slot == slot
    @lbds_prop_frame_slot = slot
    time = now - @lbds_prop_started_at
    pause_anim = $PokemonSystem && $PokemonSystem.respond_to?(:autotile_animations) &&
                 $PokemonSystem.autotile_animations == 1
    frame_cache = {}
    anchor_cache = {}
    @lbds_prop_sprites.each do |entry|
      sprite, p, cx, cy, run, priority, old_frame, track = entry
      id = p.object_id
      key = [id, track]
      frame = frame_cache[key]
      unless frame
        config = track == :parallel ? p[:parallel] : p
        phase = track == :parallel ? config[:phase] : 0
        if p[:timing_mode] == 'independent'
          phase += LBDSAnimatedProps.phase_from_id(p[:id], config[:frames])
        end
        elapsed_frames = (time * config[:fps]).floor + phase
        frame = pause_anim ? 0 : (config[:loop] ? elapsed_frames % config[:frames] : [elapsed_frames, config[:frames] - 1].min)
        frame_cache[key] = frame
      end
      if frame != old_frame
        sprite.src_rect.set((frame * p[:frame_width] + p[:source_x] + cx) * 32,
                            (p[:source_y] + cy) * 32, run * 32, 32)
        entry[6] = frame
      end
      next unless geometry_changed
      origin = anchor_cache[id]
      unless origin
        sx = p[:x] * Game_Map::TILE_WIDTH - mx
        sy = p[:y] * Game_Map::TILE_HEIGHT - my
        sx = (sx - Graphics.width / 2) * zx + Graphics.width / 2 if zx != 1
        sy = (sy - Graphics.height / 2) * zy + Graphics.height / 2 if zy != 1
        origin = [sx, sy]
        anchor_cache[id] = origin
      end
      sx = origin[0] + cx * Game_Map::TILE_WIDTH * zx
      sy = origin[1] + cy * Game_Map::TILE_HEIGHT * zy
      if visual25d
        cell_y = p[:y] + cy
        row = Visual25D.grid_row_for_map_cell(@map, cell_y)
        if priority == 0
          top = Visual25D.row_top_any(row)
          bottom = Visual25D.row_top_any(row + 1)
          scale = Visual25D.row_width_scale_any(row + 1)
          taper = Visual25D.row_taper(row)
        else
          # Misma base de columna y profundidad Z que un tile raised.
          base_row = row + priority - 1
          feet = Visual25D.row_top_any(base_row + 1)
          unit = Visual25D.row_unit(base_row)
          unit = Visual25D.vertical_unit_at(sy + priority * Game_Map::TILE_HEIGHT) if unit <= 0
          top = (feet - priority * unit).round
          bottom = (feet - (priority - 1) * unit).round
          scale = Visual25D.row_width_scale_any(base_row)
          taper = 1.0
        end
        sprite.x = Visual25D.project_x(sx, scale)
        sprite.y = top
        new_zx = zx * scale
        new_zy = [bottom - top, 1].max.to_f / 32.0
        sprite.zoom_x = new_zx if (sprite.zoom_x - new_zx).abs > 0.001
        sprite.zoom_y = new_zy if (sprite.zoom_y - new_zy).abs > 0.001
        if sprite.respond_to?(:taper=) && sprite.respond_to?(:taper)
          sprite.taper = taper if (sprite.taper.to_f - taper).abs > 0.001
        end
        base_z = ((row + priority + 1) * TilemapRenderer::DISPLAY_TILE_HEIGHT) -
                 (Visual25D.row_offset || 0) + 1 + priority
        sprite.z = (priority == 0 ? 0 : Visual25D.raised_tile_z(base_z)) +
                   [p[:layer], 5].min + (track == :parallel ? 1 : 0)
        sprite.visible = (sprite.x + run * 32 * new_zx > 0 &&
                          sprite.y + 32 * new_zy > 0 &&
                          sprite.x < Graphics.width && sprite.y < Graphics.height)
      else
        if sprite.respond_to?(:taper=) && sprite.respond_to?(:taper)
          sprite.taper = 1.0 if (sprite.taper.to_f - 1.0).abs > 0.001
        end
        sprite.x = sx.round
        sprite.y = sy.round
        sprite.zoom_x = zx
        sprite.zoom_y = zy
        sprite.z = (priority == 0 ? 0 : sy.round + Game_Map::TILE_HEIGHT * (priority + 1) + 1) +
                   [p[:layer], 5].min + (track == :parallel ? 1 : 0)
        sprite.visible = (sx + run * Game_Map::TILE_WIDTH * zx > 0 &&
                          sy + Game_Map::TILE_HEIGHT * zy > 0 &&
                          sx < Graphics.width && sy < Graphics.height)
      end
    end
  end

  def update
    super
    lbds_props_update_sprites
  end

  def lbds_props_performance_stats
    { total_placements: (@lbds_prop_placements || []).length,
      active_placements: (@lbds_prop_groups || {}).length,
      active_sprites: (@lbds_prop_sprites || []).length,
      cached_bitmaps: (@lbds_prop_bitmaps || {}).length }
  end

  def dispose
    if @lbds_prop_sprites
      @lbds_prop_sprites.each { |item| item[0].dispose unless item[0].disposed? }
      @lbds_prop_sprites.clear
    end
    if @lbds_prop_bitmaps
      @lbds_prop_bitmaps.each_value { |bmp| bmp.dispose unless bmp.disposed? }
      @lbds_prop_bitmaps.clear
    end
    super
  end
end

# F12 can re-evaluate scripts in the same Ruby VM. Repeated prepends of
# dynamically-redefined wrapper modules create an ever-growing `super` chain.
# Compare ancestor names as well as object identity to reject old wrappers that
# share a name after a hot reload (and keep this safe for older saved projects).
unless Game_Map.ancestors.any? { |mod| mod.equal?(LBDSAnimatedPropsMap) || mod.name == 'LBDSAnimatedPropsMap' }
  Game_Map.prepend(LBDSAnimatedPropsMap)
end
unless Spriteset_Map.ancestors.any? { |mod| mod.equal?(LBDSAnimatedPropsSpriteset) || mod.name == 'LBDSAnimatedPropsSpriteset' }
  Spriteset_Map.prepend(LBDSAnimatedPropsSpriteset)
end
